// The onion: each middleware logs on the way down, the handler logs at the center,
// and (if next() was called) each middleware logs again on the way up.
function mw(name) {
  return function (req, next) {
    req.order.push(name + ':down');
    next();
    req.order.push(name + ':up');
  };
}
// auth that REFUSES to call next() -> short-circuits the chain (think 401).
function authBlock(req, next) {
  req.order.push('auth:down');
  req.order.push('auth:401'); // responds without next() -> handler never runs
}
function handler(req) {
  req.order.push('handler');
}

